cd /workspace && python3 -B submission/main.py < tmp/last.json > tmp/o.json; python3 -c "
import json,sys
sys.path.insert(0,'/workspace')
from audit import decode_image
req=json.load(open('/workspace/tmp/last.json')); out=json.load(open('/workspace/tmp/o.json'))
for ci,(case,res) in enumerate(zip(req['cases'],out['cases'])):
    for vi,v in enumerate(res['versions']):
        starts=[int(x,16) for x in v['starts']]
        try:
            decode_image(v['image'],starts,v['hops']); print(ci,vi,'ok R',len(starts))
        except Exception as e:
            print(ci,vi,'FAIL',e,'R',len(starts)); print(' starts',[hex(s) for s in starts]); print(' hops',v['hops']); print(' img',v['image'][:200])
"
